S=[[] for _ in range(5)]
def e(n,title,prompt,qa,qb,aa,ab,steps,topics,note):
 disc={'m':'Matemática','p':'Física','q':'Química'}[topics[0][0]]
 S[n-1].append(dict(id=f's{n}-q{len(S[n-1])+1}',discipline=disc,title=title,prompt=prompt,parts=[qa,qb],answers=[aa,ab],answer='a) '+aa+' b) '+ab,steps=steps,topics=topics,note=note,kind='exam',rubric=['0,25 pela montagem ou relação correta; 0,25 pelo resultado justificado do item a.','0,25 pelo desenvolvimento; 0,25 pelo resultado e condições/unidades do item b.']))
# SIMULADO 1: consolidar leitura, unidades e conferência.
e(1,'Quadrados e frações',r'Considere $A=51^2-49^2$ e $B=(x^2-4)/(x^2-2x)$.','Calcule A usando fatoração.','Simplifique B e escreva as restrições.','200.',r'$(x+2)/x$; $x\ne0,2$.',[r'a) $(51-49)(51+49)=2\cdot100=200$.',r'b) $x^2-4=(x-2)(x+2)$ e $x^2-2x=x(x-2)$.',r'Cancele x−2 apenas onde é não nulo; preserve x≠0 e x≠2.'],['m01','m02'],'Diferença de quadrados não é quadrado da diferença.')
e(1,'Clubes da escola','Em80 alunos,45 participam de música,38 de esporte e10 de nenhum clube.','Determine quantos participam dos dois e preencha as quatro regiões do Venn.','Um prêmio de R$180 é dividido inversamente a2 e3 faltas. Determine as parcelas.','13; só música32, só esporte25, ambos13, nenhum10.','R$108 e R$72.',['a) União=80−10=70; interseção=45+38−70=13. Subtraia13 de cada total.','b) Recíprocos1/2:1/3=3:2. Cada parte vale180/5=36.','3·36=108 e2·36=72; a soma é180.'],['m03','m04'],'Use o total de alunos do enunciado, não a soma dos clubes.')
e(1,'Oficina e equilíbrio financeiro','Uma oficina gasta R$420 para produzir20 peças e R$780 para50 peças. O custo é afim e cada peça é vendida por R$20.','Determine C(x).','Determine a menor quantidade inteira para obter lucro estritamente positivo.','C(x)=12x+180.','23 peças.',['a) Taxa=(780−420)/(50−20)=12. Intercepto420−12·20=180.','b) L=20x−(12x+180)=8x−180.','L>0 dáx>22,5; a menor quantidade inteira é23.'],['m06','m05'],'Lucro é receita menos custo, e a resposta deve ser um número inteiro.')
e(1,'Expoentes e domínio',r'Resolva as duas situações em números reais.',r'$9^{x-1}\le27$.',r'$\log_2(x-1)+\log_2(x+1)=3$.',r'$x\le5/2$.','x=3.',[r'a) $3^{2x-2}\le3^3$: $2x-2\le3$.',r'b) Domínio x>1. Pela propriedade do produto, $(x-1)(x+1)=8$.',r'$x^2=9$, raízes ±3. Só3 pertence ao domínio.'],['m08','m09','m07'],'Cheque o domínio antes de aceitar as raízes.')
e(1,'Quadrado e círculos','Quatro círculos de raio R estão em duas filas dentro de um quadrado de lado12 cm, tangentes entre si e aos lados. Um círculo central de raio r é tangente aos quatro.','Determine R e r.','Calcule a área do quadrado não ocupada pelos quatro círculos maiores (inclua o círculo pequeno nessa área).',r'$R=3$ cm; $r=3(\sqrt2-1)$ cm.',r'$144-36\pi$ cm².',[r'a) $4R=12\Rightarrow R=3$. A distância do centro do quadrado a um centro maior vale $R\sqrt2$.',r'$R+r=R\sqrt2$, logo $r=3(\sqrt2-1)$.',r'b) Área quadrado=144; quatro discos=4π·9=36π. Subtraia.'],['m11','m12','m13'],'O lado contém quatro raios, e áreas usam o raio ao quadrado.')
e(1,'Caminho e velocidade','Um móvel vai da posição−10 m à posição30 m e depois até10 m. Gasta10 s no total.','Determine distância, deslocamento e velocidade média.','Outro vetor velocidade tem módulo36 km/h e componentes positivas com cosθ=0,8 e senθ=0,6. Determine as componentes em m/s.','60 m;20 m;2 m/s.','vx=8 m/s;vy=6 m/s.',['a) Distância40+20=60; deslocamento10−(−10)=20; média20/10=2.','b)36/3,6=10 m/s.','vx=10·0,8=8;vy=10·0,6=6.'],['p01','p02'],'Distância e deslocamento respondem a perguntas diferentes.')
e(1,'Mesa e queda','Uma esfera sai horizontalmente de uma mesa de1,25 m de altura e toca o chão2 m à frente da borda. Despreze o ar e use g=10 m/s².','Determine o tempo de queda e a velocidade horizontal.','Determine a componente vertical e o módulo da velocidade ao tocar o solo.','0,5 s;4 m/s.','5 m/s para baixo;√41 m/s ≈6,40 m/s.',['a)1,25=5t²; t=0,5. vx=2/0,5=4.','b)vy=10·0,5=5.','Módulo=√(4²+5²)=√41. A raiz faz parte da resposta.'],['p04','p03'],'Não pare em v²; conclua o módulo.')
e(1,'Fonte pontual e espelho','Uma fonte pontual está a2 m de um disco opaco de10 cm de diâmetro; a tela está a8 m da fonte.','Determine o diâmetro da sombra.','Um raio faz35° com a superfície de um espelho. Determine incidência e reflexão medidos com a normal.','40 cm.','i=r=55°.',['a)Ampliação8/2=4; sombra4·10=40 cm.','b)A normal é perpendicular à superfície.','i=90−35=55°; r=i.'],['p07','p08'],'Meça ângulos com a normal e distâncias a partir da mesma referência.')
e(1,'Aquecimento em etapas','100 g de gelo a−10°C recebem calor até virarem água a20°C. Use c_gelo=0,5 cal/(g·°C), L_f=80 cal/g e c_água=1 cal/(g·°C).','Calcule o calor total.','Uma barra de1 m, α=2×10⁻⁵ °C⁻¹, aquece no mesmo intervalo de−10 a20°C. Determine ΔL em mm.','10 500 cal.','0,6 mm.',['a)Até0°C:100·0,5·10=500. Fusão:100·80=8000. Água:100·1·20=2000. Total10500.','b)ΔT=20−(−10)=30°C.','ΔL=1·2×10⁻⁵·30=0,0006 m=0,6 mm.'],['p09','p10'],'A mudança de fase precisa de energia mesmo sem variação de temperatura.')
e(1,'Roda e transmissão','Uma roda de raio0,5 m gira a120 rpm e aciona por correia sem deslizamento uma polia de raio0,2 m.','Calcule a frequência, a velocidade angular e a velocidade na borda da roda.','Determine a frequência da polia e a aceleração centrípeta na borda da roda.',r'$2$ Hz; $4\pi$ rad/s; $2\pi$ m/s.',r'$5$ Hz; $8\pi^2$ m/s².',[r'a)120/60=2 Hz; ω=2πf=4π; v=ωR=2π.',r'b)Na correia, $2\pi f_1R_1=2\pi f_2R_2$, então f₂=5 Hz.',r'$a_c=v^2/R=4\pi^2/0,5=8\pi^2$.'],['p05'],'Correia iguala velocidades lineares nas bordas, não frequências.')
e(1,'Partículas e fase',r'Considere ${}^{27}_{13}Al^{3+}$ e água líquida evaporando.','Conte prótons, nêutrons e elétrons do íon.','Classifique a evaporação quanto à natureza física/química e à troca de calor.','13 p;14 n;10 e.','Física e endotérmica.',['a)p=13;n=27−13=14;e=13−3=10.','b)As moléculas continuam H₂O: mudança física.','A passagem para gás absorve energia do entorno.'],['q02','q01'],'A carga positiva significa perda de elétrons, não ganho de prótons.')
e(1,'Localização periódica','Um átomo neutro tem Z=17.','Escreva a configuração eletrônica completa e a distribuição por camadas.','Determine período, grupo e configuração do ânion monovalente.',r'$1s^22s^22p^63s^23p^5$;2,8,7.','Período3; grupo17 (halogênios); Cl⁻=[Ar].',[r'a)Preencha2,2,6,2,5 elétrons nos subníveis; soma17.','b)Maior n=3; sete elétrons externos.','O ânion ganha1: total18, configuração de Ar.'],['q03','q04'],'Período e grupo não são sinônimos.')
e(1,'Água e óxido de magnésio','Use H=1 elétron de valência, O=6; Mg forma Mg²⁺ e O forma O²⁻.','Desenhe Lewis da água, incluindo pares livres.','Escreva a fórmula iônica neutra entre Mg e O e explique por que os índices podem ser simplificados.','H–O–H, dois pares livres no O.','MgO; proporção1:1.',['a)Total8 elétrons:4 em duas ligações O–H e4 em dois pares livres.','b)Uma carga+2 equilibra uma−2.','Mg₂O₂ também teria carga zero, mas não é a menor proporção da unidade de fórmula.'],['q05'],'Inclua elétrons não ligantes e reduza os índices iônicos à menor proporção.')
e(1,'Gás no frasco','Um frasco vazio tem50 g e cheio de CO₂ tem54,4 g. Use C=12,O=16,N_A=6×10²³ e volume molar22,4 L/mol nas CNTP.','Determine mols de CO₂ e volume do gás.','Determine o número de moléculas e de átomos de oxigênio.','0,1 mol;2,24 L.','6×10²² moléculas;1,2×10²³ átomos de O.',['a)Gás=4,4 g; M=44; n=0,1. V=0,1·22,4.','b)N=0,1·6×10²³=6×10²².','Cada CO₂ tem2O: multiplique por2, não por3.'],['q06'],'Subtraia a tara e conte apenas o elemento solicitado.')
e(1,'Água formada e sobra',r'4 g de $H_2$ reagem com48 g de $O_2$. Use H=1,O=16.', 'Balanceie a reação e identifique o limitante.','Calcule a massa de água formada e a massa do reagente que sobra.','2H₂+O₂→2H₂O;H₂ limita.','36 g de água;16 g de O₂.',['a)nH₂=4/2=2 mol; nO₂=48/32=1,5 mol. Compare2/2=1 com1,5/1.','b)Formam-se2 mol de água:36 g. Consome-se1 mol de O₂=32 g.','Sobra48−32=16 g. Conservação:4+48=36+16.'],['q08'],'O menor número de mols sozinho não define o limitante.')
# SIMULADO 2: modelagem e sinais.
e(2,'Cubo e raiz principal',r'Sabe-se que $x+1/x=3$, com x real não nulo.',r'Calcule $x^3+1/x^3$.',r'Calcule $\sqrt{(-7)^2}+(1/4)^{-1/2}$.','18.','9.',[r'a)$(x+1/x)^3=x^3+1/x^3+3(x+1/x)$.',r'$27=x^3+1/x^3+9$, logo18.',r'b)Raiz principal:7. Potência inversa:2. Soma9.'],['m02','m01'],'Não confunda os coeficientes do cubo com os do quadrado.')
e(2,'Encomenda e divisão','Uma compra de30 cadernos e canetas custa R$180. Caderno custa R$12 e caneta R$3.','Determine a quantidade de cada produto.','Divida R$210 diretamente em2:3:5.','10 cadernos;20 canetas.','R$42,R$63,R$105.',['a)x+y=30;12x+3y=180. Subtraia3(x+y)=90:9x=90, x=10,y=20.','b)Soma dos pesos=10; uma parte=21. Parcelas42,63,105.','Confira:10·12+20·3=180 e42+63+105=210.'],['m05','m04'],'Defina variáveis e confira os totais nas duas situações.')
e(2,'Jardim retangular','Um jardim retangular tem perímetro28 m e área48 m².','Determine seus lados e a diagonal.','Uma faixa interna de1 m de largura acompanha todo o contorno. Determine a área da parte central restante.','6 m e8 m;diagonal10 m.','24 m².',['a)x+y=14 e xy=48. x(14−x)=48; x²−14x+48=0, raízes6 e8.','Diagonal=√(36+64)=10.','b)A faixa retira2 m de cada dimensão:centro4×6=24 m².'],['m07','m13','m12'],'O perímetro envolve duas vezes cada lado; a faixa reduz as duas extremidades.')
e(2,'Decaimento e logaritmo',r'Uma população segue $N(t)=80(1/2)^t$, com t em horas e t≥0.', 'Quando N(t)≤10?',r'Resolva $\log_x(x+6)=2$ em R.',r'$t\ge3$ h.','x=3.',[r'a)$(1/2)^t\le1/8=(1/2)^3$. Inverta a comparação dos expoentes: t≥3.',r'b)Domínio x>0,x≠1,x+6>0. Equivalência: x²=x+6.',r'Raízes3 e−2; só3 é admissível.'],['m08','m09'],'A base fracionária inverte a ordem; a base variável impõe condições.')
e(2,'Hexágono e ângulos',r'Um hexágono regular está circunscrito a uma circunferência de raio $3\sqrt3$ cm.', 'Determine seu lado e sua área.','Duas paralelas são cortadas por uma transversal que faz125° em um dos encontros. Qual é o ângulo agudo no outro encontro?','6 cm;54√3 cm².','55°.',[r'a)Raio é apótema: $3\sqrt3=l\sqrt3/2$, então l=6.',r'Área=P·apótema/2=36·3√3/2=54√3.',r'b)O agudo é suplementar a125°:55°. O paralelismo conserva essa medida.'],['m11','m10','m13'],'No polígono circunscrito, o raio do círculo é a apótema.')
e(2,'Gráfico por trechos','Um gráfico v×t tem v=6 m/s de0 a4 s, v=0 de4 a6 s e v=−3 m/s de6 a10 s.','Determine deslocamento e distância total.','Determine velocidade média e rapidez média.','12 m;36 m.','1,2 m/s;3,6 m/s.',['a)Áreas:6·4=24;0;−3·4=−12. Deslocamento12;distância24+12=36.','b)Tempo total10 s, incluindo a parada.','Velocidade12/10;rapidez36/10.'],['p02'],'Inclua a parada no tempo total.')
e(2,'Reação e frenagem','Um carro a18 m/s está a45 m de um obstáculo. O motorista reage após0,5 s e freia uniformemente até parar exatamente antes dele.','Determine a distância disponível para a frenagem.','Calcule a aceleração na frenagem e o tempo total até parar.','36 m.','−4,5 m/s²;4,5 s.',['a)Reação:18·0,5=9 m. Restam45−9=36.','b)0=18²+2a·36; a=−4,5.','0=18−4,5t_f dá4 s. Tempo total0,5+4=4,5 s.'],['p03'],'Não imponha desaceleração durante o tempo de reação.')
e(2,'Alturas no espelho','Um olho está a1,4 m de altura e uma lâmpada diretamente acima dele a2,6 m. Ambos estão a mesma distância de um espelho vertical.','Determine a altura de reflexão do raio que vai da lâmpada ao olho.','Se o olho está a0,8 m do espelho, qual a distância reta entre o olho e a imagem da lâmpada?','2,0 m.','2,0 m.',['a)Pela simetria, altura média:(1,4+2,6)/2=2,0.','b)Separação horizontal0,8+0,8=1,6 m; vertical2,6−1,4=1,2 m.','Distância=√(1,6²+1,2²)=√4=2 m.'],['p08','m12'],'A imagem fica atrás do espelho; a distância horizontal entre olho e imagem é2d.')
e(2,'Patamar e dilatação','500 g de uma substância aquecem de20 a80°C enquanto Q acumulado vai de10 000 a25 000 cal. Em seguida há patamar até85 000 cal.','Determine c e o calor latente da transformação.','Uma chapa de área2 m² tem α=10⁻⁵ °C⁻¹. Estime ΔA ao aquecer60°C.','0,5 cal/(g·°C);120 cal/g.','0,0024 m².',['a)Q sensível=15000;c=15000/(500·60)=0,5. No patamar Q=85000−25000=60000;L=120.','b)β≈2α=2×10⁻⁵.','ΔA≈2·2×10⁻⁵·60=0,0024.'],['p09','p10'],'Cada trecho recebe a diferença entre valores do calor acumulado.')
e(2,'Blocos ligados','Um bloco de4 kg está em mesa lisa e ligado por fio e polia ideais a um bloco pendente de1 kg. Use g=10 m/s².','Desenhe as forças e determine a aceleração do conjunto.','Determine a tração e verifique-a pela equação do bloco pendente.','2 m/s².','8 N;10−8=1·2.',['a)Mesa:peso40N para baixo,normal40N para cima,tração horizontal. Pendente:peso10N para baixo eT para cima.','Somando equações:T=4a;10−T=a. Logo10=5a,a=2.','b)T=4·2=8N. Verificação10−8=2.'],['p06'],'Peso e tração não são iguais no corpo acelerado.')
e(2,'Isótonos e íons',r'${}^{35}_{17}X^-$ é isótono de ${}^{A}_{19}Y$ neutro.', 'Determine A e o número de elétrons de cada espécie.','Se o núcleo de Y emitisse uma alfa, quais seriam os números de massa e atômico do núcleo resultante?','A=37;X⁻18 elétrons;Y19.','A=33;Z=17.',['a)N=35−17=18. ParaY:A=19+18=37. X⁻ ganha1elétron;Y é neutro.','b)Emissão alfa retira4 unidades de massa e2prótons.','37−4=33;19−2=17.'],['q02'],'A igualdade de nêutrons não implica igualdade de elétrons.')
e(2,'Metal e camada externa','Um átomo de ferro tem configuração [Ar]3d⁶4s².','Qual o Z e a configuração de Fe³⁺?','Qual a camada de valência do átomo neutro? Por que ela não é indicada pelo3d?','Z=26;[Ar]3d⁵.','n=4, com2 elétrons; maior n define camada externa.',['a)18+6+2=26. Retire primeiro2 elétrons4s e depois1do3d.','b)A maior camada ocupada no neutro é4.','A ordem de preenchimento não é simplesmente a ordem dos números de camada.'],['q03','q04'],'Ao ionizar, retire elétrons da camada de maior n primeiro.')
e(2,'Íons e moléculas','Considere Al³⁺,F⁻ e a molécula CO₂.','Determine a fórmula do fluoreto de alumínio e represente os íons com octeto do flúor.','Represente Lewis de CO₂ e conte elétrons de valência.','AlF₃;umAl³⁺ e3F⁻ com8 elétrons em torno de cada F.','O=C=O;16 elétrons;2pares livres porO.',['a)+3+3·(−1)=0. Os ânions são representados entre colchetes com carga−.','b)4+2·6=16. Duas ligações duplas utilizam8.','Os8restantes formam4pares livres,2em cadaO.'],['q05'],'Não escreva Al³F: carga é sobrescrito; índice conta átomos ou íons.')
e(2,'Fórmula e quantidade',r'Um composto tem fórmula mínima $CH_2O$ e massa molar60 g/mol. Uma amostra pesa15 g. Use C=12,H=1,O=16,N_A=6×10²³.', 'Determine a fórmula molecular e os mols na amostra.','Calcule o número total de átomos na amostra.','C₂H₄O₂;0,25 mol.','1,2×10²⁴ átomos.',['a)Mínima30;fator60/30=2. FórmulaC₂H₄O₂. n=15/60=0,25.','b)Cada molécula tem8átomos. Moléculas=0,25·6×10²³=1,5×10²³.','Total=8·1,5×10²³=1,2×10²⁴.'],['q07','q06'],'Use os índices da fórmula molecular, não da mínima, para contar átomos por molécula.')
e(2,'Neutralização completa',r'0,10 mol de $H_2SO_4$ são misturados a0,15 mol de NaOH. Considere apenas neutralização completa para formar $Na_2SO_4$ e água, conforme a proporção global. Use M(Na₂SO₄)=142 g/mol.', 'Balanceie e determine o reagente limitante.','Calcule a massa de sal formada e os mols de ácido restantes no modelo.','H₂SO₄+2NaOH→Na₂SO₄+2H₂O;NaOH limita.','10,65 g;0,025 mol de ácido.',['a)Compare0,10/1 e0,15/2=0,075. NaOH limita.','b)Forma0,075mol deNa₂SO₄:0,075·142=10,65g.','Ácido consumido0,075;restante0,10−0,075=0,025mol. Modelo estequiométrico global; especiação aquosa não é solicitada.'],['q08','q09'],'Um mol do ácido exige dois mols da base na neutralização completa.')
# SIMULADO 3: integração de modelos.
e(3,'Notação e distributiva',r'Considere $P=(3\cdot10^{-4})(2\cdot10^6)$ e $Q=(\sqrt[3]4+1/\sqrt[3]2)\sqrt[3]2$.','Calcule P em notação científica.','Simplifique Q exatamente.',r'$6\cdot10^2$.','3.',[r'a)Coeficientes:3·2=6; expoentes:−4+6=2.',r'b)Distribua: $\sqrt[3]4\sqrt[3]2+1=\sqrt[3]8+1=3$.'],['m01','m02'],'Não distribua uma raiz sobre uma soma; distribua o fator que multiplica a soma.')
e(3,'Três atividades','Em uma turma,18 fazem teatro,20 música e22 esporte. Há8 em teatro∩música,7 em teatro∩esporte,9 em música∩esporte e4 nas três. Seis não fazem nenhuma.','Determine o total de alunos.','Determine quantos participam de exatamente uma atividade.','46.','24.',['a)União=18+20+22−8−7−9+4=40; com os6 de fora,total46.','b)Só teatro=18−8−7+4=7. Só música=20−8−9+4=7.','Só esporte=22−7−9+4=10. Soma7+7+10=24.'],['m03'],'Preencha regiões exclusivas a partir do centro.')
e(3,'Reservatório e consumo','Um reservatório perde água a taxa constante. Após2 h contém720 L; após5 h contém600 L.','Determine V(t) e o instante em que resta metade do volume inicial.','Um veículo rende16 km/L a determinada velocidade. Quantos litros precisa para240 km e qual sua autonomia com35 L?','V(t)=800−40t;10 h.','15 L;560 km.',['a)Taxa=(600−720)/(5−2)=−40 L/h. 720=−40·2+b dáb=800.','Metade400 L:400=800−40t, t=10.','b)240/16=15 L;35·16=560 km.'],['m06','m04'],'Leia a grandeza de cada eixo; velocidade e eficiência não são intercambiáveis.')
e(3,'Exponencial entre limites',r'Considere $y=(1/2)^{-x^2+2x}$.',r'Determine x para $1<y<8$.',r'Resolva $\log_3 z=1+2/\log_3 z$.',r'$(-1,0)\cup(2,3)$.',r'$z=9$ ou $z=1/3$.',[r'a)y=$2^{x^2-2x}$. Assim $0<x^2-2x<3$. A primeira condição dáx<0 oux>2.',r'A segunda: $x^2-2x-3<0$, raízes−1 e3; então−1<x<3. Interseccione.',r'b)Useu=log₃z≠0. u²=u+2, raízes2 e−1. z=3²=9 ou3⁻¹=1/3. Ambas satisfazem domínio z>0,z≠1.'],['m08','m09','m07'],'As duas desigualdades precisam valer simultaneamente.')
e(3,'Triângulo e círculo',r'ABC é equilátero inscrito em uma circunferência. D está na bissetriz interna do ângulo A, com AB=AD e BD=2. O ângulo BAD é30°. Use $\sin75°=(\sqrt6+\sqrt2)/4$.','Determine AB pela lei dos senos.','Determine o raio circunscrito a ABC e a área de ABC.',r'$\sqrt6+\sqrt2$.',r'$R=(\sqrt6+\sqrt2)/\sqrt3$; $A=3+2\sqrt3$.',[r'a)ABD é isósceles; B=D=75°. $AB/\sin75°=2/\sin30°=4$, então AB=√6+√2.',r'b)Equilátero:R=l/√3. Área=l²√3/4.',r'l²=8+4√3; área=(8+4√3)√3/4=2√3+3.'],['m10','m11','m12','m13'],'O ângulo75° vem do isósceles; não suponha um triângulo retângulo.')
e(3,'Vetores no plano',r'Adote $\vec A=(4,-2)$ N e $\vec B=(-1,3)$ N.',r'Calcule $\vec R=\vec A+2\vec B$ e seu módulo.','Um móvel percorre90 m em30 s e60 m em20 s, sempre no mesmo sentido. Determine a velocidade média total em km/h.',r'$(2,4)$ N; $2\sqrt5$ N.','10,8 km/h.',[r'a)2B=(−2,6). R=(2,4), módulo√20=2√5.',r'b)Distância150m;tempo50s; média3m/s.','Converta:3·3,6=10,8 km/h.'],['p01','p02'],'Some componentes, não comprimentos de setas.')
e(3,'Evento antes do impacto','Um objeto é lançado horizontalmente a12 m/s, de uma altura de80 m. Use g=10 m/s² e despreze o ar. Um sensor é acionado1 s antes do impacto.','Determine o tempo até acionar o sensor e a distância horizontal até esse instante.','Determine o módulo da velocidade nesse instante.','3 s;36 m.','√1044 m/s =6√29 m/s ≈32,3 m/s.',['a)Tempo total:80=5t², t=4. Sensor em4−1=3s. x=12·3=36.','b)vy=10·3=30m/s;vx=12.','v=√(12²+30²)=√1044=6√29.'],['p04'],'“Um segundo antes de cair” não é um segundo depois de soltar.')
e(3,'Fonte extensa','Uma fonte de diâmetro4 cm está a1 m de um disco de diâmetro20 cm. A tela está a3 m da fonte, com centros alinhados e planos paralelos.','Calcule os raios da umbra e do limite externo da penumbra.','Calcule a espessura do anel e o diâmetro da umbra.','26 cm e34 cm.','8 cm e52 cm.',['a)Use raios2 e10cm, ampliação3. Umbra:2+(10−2)·3=26.','Limite externo:−2+(10+2)·3=34.','b)Espessura34−26=8; diâmetro2·26=52.'],['p07'],'Faça dois raios-limite e diferencie raio de diâmetro.')
e(3,'Mistura e sólido','200 g de água a60°C são misturados a300 g de água a20°C, sem perdas nem mudança de fase.','Determine a temperatura de equilíbrio.','Um cubo de volume100 cm³, α=2×10⁻⁵ °C⁻¹, aquece50°C. Estime a variação de volume.','36°C.','0,3 cm³.',['a)200(T−60)+300(T−20)=0;500T=18000;T=36.','b)γ≈3α=6×10⁻⁵.','ΔV=100·6×10⁻⁵·50=0,3 cm³.'],['p09','p10'],'A temperatura de equilíbrio usa pesos proporcionais às massas, não a média simples.')
e(3,'Órbita e tempo','Um planeta fictício orbita o Sol com periélio2 UA e afélio6 UA. Use T²=a³, T em anos e a em UA.','Determine a e T.','Se o raio vetor varre12 unidades de área em3 meses, quanto varre em5 meses? O planeta é mais rápido no periélio ou no afélio?','a=4 UA;T=8 anos.','20 unidades de área;no periélio.',['a)a=(2+6)/2=4. T²=64, T=8.','b)Velocidade areolar12/3=4 unidades/mês. Em5meses,20.','Perto do Sol, um arco maior é necessário para varrer a mesma área no mesmo tempo; rapidez maior.'],['p11'],'A terceira lei usa semieixo maior, não o afélio.')
e(3,'Molécula e condensação',r'Considere $C_2H_6O$ e $O_3$.','Conte elementos e átomos em cada fórmula e classifique simples/composta.','Gotas aparecem fora de um copo frio. Identifique a origem e o processo com sua troca de calor.','C₂H₆O:3 elementos,9 átomos,composta. O₃:1 elemento,3 átomos,simples.','Vapor de água do ar;condensação exotérmica.',['a)Conte símbolos diferentes e some índices. O₃ contém apenas oxigênio.','b)O vapor encontra a superfície fria e passa a líquido.','A condensação libera calor; a água não atravessou o vidro.'],['q01'],'Quantidade de átomos não é quantidade de elementos.')
e(3,'Molibdênio e porcentagem','Mo tem Z=42 e configuração fundamental [Kr]4d⁵5s¹.','Determine a configuração de Mo⁺ e seu número de elétrons.','Determine a porcentagem de elétrons em subníveis s do cátion.','[Kr]4d⁵;41 elétrons.','8/41×100≈19,51%.',['a)Remove-se o elétron5s;42−1=41.','b)No núcleo[Kr],1s²2s²3s²4s² somam8 elétrons s.','Divida8 pelo total41 e multiplique100.'],['q03'],'Mantenha a configuração excepcional ao passar de um item ao seguinte.')
e(3,'Família e Lewis','Um átomo representativo tem configuração externa3s²3p⁴.','Identifique grupo, período e carga usual de seu ânion monoatômico.','Esse elemento é S. Represente Lewis de H₂S, com6 elétrons de valência do S e1 de cada H.','Grupo16,período3,carga−2.','H–S–H;dois pares livres no S.',['a)Seis elétrons externos; família dos calcogênios. Maior n=3. Ganha2 para completar octeto.','b)Total8 elétrons:4 nas ligações simples e4 nos dois pares livres.'],['q04','q05'],'Não confunda o número6 de elétrons externos com a numeração moderna do grupo16.')
e(3,'Composição de um composto','Uma substância tem40%C,6,67%H e53,33%O; sua massa molar é180 g/mol. Use C=12,H=1,O=16.','Determine fórmulas mínima e molecular.','Determine mols de moléculas e mols de átomos de carbono em9 g.','CH₂O eC₆H₁₂O₆.','0,05 mol de moléculas;0,30 mol de átomos de C.',['a)Em100g, mols aproximados3,333;6,67;3,333. Razão1:2:1, massa mínima30.','Fator180/30=6.','b)n=9/180=0,05;cada molécula tem6C, logo0,05·6=0,30mol deC.'],['q07','q06'],'Massa molar refere-se à fórmula molecular.')
e(3,'Combustível e combustão','Considere CH₃–CH₂–CH₂–CH₃, com C=12,H=1,O=16.','Dê nome, fórmula molecular e equação de combustão completa.','Calcule a massa de CO₂ produzida pela combustão completa de5,8 g, com O₂ em excesso.','Butano,C₄H₁₀;2C₄H₁₀+13O₂→8CO₂+10H₂O.','17,6 g de CO₂.',['a)Cadeia aberta de4C só com simples:butano. Balanceie primeiroC eH, depoisO.','b)M=58;5,8g=0,1mol de butano. Relação1:4 comCO₂.','CO₂=0,4mol;M=44; m=17,6g.'],['q10','q08'],'Os coeficientes são relações molares, não relações diretas de massa.')
# SIMULADO 4: escolher a representação adequada.
e(4,'Dízima e expressão racional',r'Considere $u=2{,}333\ldots$ e $F=(x^2-9)/(x^2-6x+9)$.','Escreva u como fração e calcule u−1/6.','Simplifique F, indicando seu domínio.','7/3;13/6.',r'$(x+3)/(x-3)$, x≠3.',[r'a)10u−u=23,333…−2,333…=21;u=7/3. Diferença14/6−1/6=13/6.',r'b)Numerador=(x−3)(x+3);denominador=(x−3)².','Cancele um fatorx−3; a exclusãox≠3 permanece.'],['m01','m02'],'A parte inteira entra na fração geratriz.')
e(4,'Conjuntos e inversa','Dois conjuntos têm união de60 elementos, interseção de12 e B possui8 elementos a mais que A.','Determine as cardinalidades de A e B.','Ângulos de um triângulo são inversamente proporcionais a2,3 e6. Determine os ângulos e classifique.','A=32;B=40.','90°,60°,30°;retângulo.',['a)x+(x+8)−12=60;2x=64;x=32. B=40.','b)Recíprocos1/2:1/3:1/6=3:2:1. Uma parte180/6=30°.','Três partes90°, duas60°, uma30°.'],['m03','m04','m10'],'Verifique32+40−12=60 e a soma dos ângulos.')
e(4,'Função e intervalo',r'Uma reta passa por(0,−2) e(4,6). Considere também $q(x)=x^2-4x-5$.','Determine a reta e seu zero.','Resolva q(x)≤0.','f(x)=2x−2;zero1.',r'$[-1,5]$.',[r'a)Taxa(6+2)/4=2 e intercepto−2. Zero:2x−2=0.',r'b)q=(x−5)(x+1). Raízes−1 e5.',r'Parábola para cima: não positiva entre as raízes, incluindo ambas.'],['m06','m07'],'Raízes são fronteiras; o conjunto solução é um intervalo.')
e(4,'Curva e reta',r'$f(x)=ka^x$ passa por A=(1,4) e B=(2,2).','Determine k,a e f(0).','Determine a função afim g que passa por A e B; compare f(3) e g(3).','k=8;a=1/2;f(0)=8.','g(x)=−2x+6;f(3)=1,g(3)=0.',['a)a=2/4=1/2;4=k/2, k=8.','b)Inclinação da reta=(2−4)/(2−1)=−2. 4=−2·1+b,b=6.','f(3)=8/8=1;g(3)=−6+6=0. Curva e reta coincidem nos dois pontos, não em todo lugar.'],['m08','m06'],'Dois pontos de uma exponencial também definem uma reta, com outra fórmula.')
e(4,'Diagonais e área','Um polígono regular tem35 diagonais. Um trapézio retângulo tem bases10 e18 cm e lado oblíquo10 cm.','Determine o número de lados e o ângulo interno do polígono.','Determine a altura e a área do trapézio.','10 lados;144°.','6 cm;84 cm².',['a)n(n−3)/2=35; n²−3n−70=0. Raízes10 e−7; aceite10. Ângulo8·180/10=144.','b)Diferença das bases8; triângulo lateral tem hipotenusa10 e cateto8. h=√(100−64)=6.','Área=(10+18)·6/2=84.'],['m11','m12','m13'],'O lado oblíquo não é a altura do trapézio.')
e(4,'Encontro e coordenadas','A e B movem-se na mesma reta com sA=−8+4t e sB=10−2t, no SI.','Determine instante e posição do encontro.','Determine a distância que cada um percorre até esse encontro.','3 s;4 m.','A:12 m;B:6 m.',['a)−8+4t=10−2t;6t=18;t=3. Posição4.','b)A:|4−(−8)|=12;B:|4−10|=6.','Confira as posições nas duas funções.'],['p02','m05'],'Iguale posições; para distância use módulo de cada trecho.')
e(4,'Inversão do movimento','Um móvel tem s₀=0,v₀=8 m/s e a=−2 m/s².','Determine o instante de inversão e a posição nesse instante.','Determine v e s em6 s e classifique o movimento nesse instante.','4 s;16 m.','v=−4 m/s;s=12 m;retrógrado e acelerado.',['a)0=8−2t dá4s. s=8·4−4²=16.','b)v=8−12=−4;s=8·6−6²=12.','v e a negativos:sentido negativo e rapidez aumentando.'],['p03'],'Aceleração negativa não significa sempre diminuir a rapidez.')
e(4,'Caminho refletido','Um raio percorre um quadrado de lado4 m pelos pontos médios sucessivos, voltando ao início após três reflexões. O tempo do circuito é4×10⁻⁸ s. Use √2≈1,4.','Determine o caminho total e o deslocamento vetorial.','Determine a rapidez média e os ângulos de incidência/reflexão.','11,2 m;deslocamento zero.','2,8×10⁸ m/s;i=r=45°.',['a)Cada trecho tem catetos2 e2:2√2. Quatro trechos:8√2≈11,2.','b)Rapidez=11,2/(4×10⁻⁸)=2,8×10⁸.','Nos lados do quadrado, trajetórias inclinadas45° à normal dãoi=r=45°.'],['p08','p01'],'Circuito fechado tem deslocamento zero, mas caminho positivo.')
e(4,'Fusão parcial','100 g de gelo a0°C recebem4 000 cal. Use L_f=80 cal/g.','Determine a massa fundida e a temperatura final.','Um recipiente de volume inicial500 cm³, γ=6×10⁻⁵ °C⁻¹, aquece40°C. Estime o volume final.','50 g;0°C, com50 g de gelo restantes.','501,2 cm³.',['a)Fundir todo gelo exigiria8000cal. Só há4000, entãom=4000/80=50g.','Enquanto restam gelo e água em fusão, temperatura0°C.','b)ΔV=500·6×10⁻⁵·40=1,2. Some ao inicial:501,2.'],['p09','p10'],'Energia insuficiente para fundir tudo não aumenta a temperatura da mistura em fusão.')
e(4,'Disco e força centrípeta','Um disco gira com período0,5 s. Um ponto está a0,25 m do centro; outro, a0,50 m.','Determine ω e as velocidades lineares dos dois pontos.','Uma peça de0,10 kg está no ponto externo. Qual o módulo da força resultante centrípeta?',r'$\omega=4\pi$ rad/s; $v_1=\pi$ e $v_2=2\pi$ m/s.',r'$0{,}8\pi^2$ N.',[r'a)f=1/T=2Hz;ω=4π. v=ωR.',r'b)ac=v₂²/R=4π²/0,5=8π².',r'F=mac=0,10·8π²=0,8π². A resultante aponta para o centro.'],['p05','p06'],'Velocidade angular igual não significa velocidade linear igual.')
e(4,'Núcleo e tabela',r'Um átomo neutro tem Z=16 e A=32.', 'Determine prótons,nêutrons,elétrons e a configuração de seu ânion2−.','Determine grupo,período e compare seu raio com o do oxigênio, no mesmo grupo e período2.','16,16,16;S²⁻=[Ar].','Grupo16;período3;S tem raio maior que O.',['a)N=32−16=16. Neutro tem16e;ânion ganha2,total18.','b)S está no grupo16 e tem3camadas ocupadas no neutro.','Descendo no grupo, aumenta o número de camadas e tende a aumentar o raio.'],['q02','q03','q04'],'Faça a configuração do íon com18 elétrons, mantendo Z=16.')
e(4,'Ureia e pares livres',r'A ureia tem fórmula $CH_4N_2O$, com carbono ligado aos dois N e ao O.', 'Represente a fórmula estrutural e a de Lewis.','Conte elétrons totais de valência e calcule a massa molar. Use C=12,H=1,N=14,O=16.','H₂N–C(=O)–NH₂;umpar livre por N e dois no O.','24 elétrons;60 g/mol.',['a)C faz dupla comO e simples com cadaN; cadaN faz outras duas ligações comH.','b)Valência:4+4+10+6=24. São16 elétrons ligantes e8 não ligantes.','M=12+4+28+16=60.'],['q05','q01'],'A fórmula molecular não mostra onde estão os pares livres.')
e(4,'Da massa às partículas','Uma amostra contém0,20 mol de ureia, CH₄N₂O, M=60 g/mol. Use N_A=6×10²³.','Calcule massa e número de moléculas.','Calcule o número total de átomos e a porcentagem em massa de N.','12 g;1,2×10²³ moléculas.','9,6×10²³ átomos;46,67%.',['a)m=0,20·60=12. N=0,20·6×10²³.','b)Cada molécula contém1+4+2+1=8 átomos:8·1,2×10²³.','Massa de N por mol=28;28/60·100≈46,67.'],['q06','q07'],'Multiplique pelo total de átomos apenas quando a pergunta pede todos os átomos.')
e(4,'Precipitação com excesso',r'NaCl+AgNO₃→NaNO₃+AgCl. Uma receita sem excesso usa58,5 g e170 g dos reagentes e produz85 g e143,5 g dos produtos, nessa ordem. Misturam-se117 g de NaCl e400 g de AgNO₃.', 'Identifique o limitante e calcule a sobra.','Determine as massas de produtos e confira a conservação.','NaCl limita;60 g de AgNO₃.','170 g de NaNO₃ e287 g de AgCl;117+400=170+287+60.',['a)NaCl é2vezes a receita; pede340g deAgNO₃. Há400, sobra60.','b)Produtos também dobram:170 e287.','Massa final457+60=517g, igual à inicial.'],['q08'],'O mesmo fator multiplica cada termo da receita.')
e(4,'Cadeia e reação',r'Considere $CH_2=CH-CH_2-CH_3$ e a decomposição $CaCO_3\to CaO+CO_2$.','Nomeie o hidrocarboneto e dê sua fórmula e classe.','Classifique a reação e calcule a massa de CO₂ ao decompor20 g de CaCO₃ puro. Use M(CaCO₃)=100 e M(CO₂)=44.','But-1-eno;C₄H₈;alceno.','Decomposição;8,8 g.',['a)Cadeia4C e dupla no carbono1. Uma dupla em cadeia aberta dáCnH2n.','b)Um reagente forma dois produtos:decomposição. n=20/100=0,2mol.','Relação1:1;CO₂=0,2·44=8,8g.'],['q10','q09','q08'],'Conte a dupla antes de aplicar a fórmula geral.')
# SIMULADO 5: revisão final e checagem independente.
e(5,'Identidade e restrição',r'Para x≠0, sabe-se $x+1/x=6$.',r'Calcule $x^2+1/x^2$.',r'Simplifique $\dfrac{x^2-1}{x^2-2x+1}-\dfrac{2x^2}{x^2-x}$ e indique onde existe.','34.','−1,para x≠0,1.',[r'a)36=x²+2+1/x², logo34.',r'b)Fatore os denominadores e numerador: $(x-1)(x+1)/(x-1)^2-2x^2/[x(x-1)]$.',r'Reduza: $(x+1-2x)/(x-1)=-1$. Exclusões originais0 e1.'],['m02','m01'],'Resultado constante não elimina restrições do enunciado.')
e(5,'Pesquisa e ingresso','Em100 pessoas,60 preferem A,55 preferem B e20 preferem ambos. Separadamente, venderam-se20 ingressos de R$15 ou R$25, arrecadando R$400.','Determine quantas pessoas não preferem nenhuma e quantas preferem apenas uma.','Determine quantos ingressos de cada preço foram vendidos.','5 nenhuma;75 apenas uma.','10 de cada.',['a)União=60+55−20=95; fora5. SóA40,sóB35,total75.','b)x+y=20;15x+25y=400.','Subtraia15(x+y)=300:10y=100;y=10;x=10.'],['m03','m05'],'Uma região exclusiva é o total do conjunto menos a interseção.')
e(5,'Parábola e viabilidade',r'No modelo de uma feira, o lucro em reais é $L(x)=-x^2+12x-20$, com x inteiro não negativo representando lotes vendidos.', 'Determine as quantidades para lucro estritamente positivo.','Determine o lucro máximo e a quantidade correspondente.','x∈{3,4,5,6,7,8,9}.','R$16 em6 lotes.',[r'a)Zeros: $x^2-12x+20=0$, raízes2 e10. Parábola de L voltada para baixo: positiva entre2 e10.',r'Restrição inteira dá3até9.',r'b)Complete o quadrado: $L(x)=16-(x-6)^2$. Máximo16 emx=6.'],['m07','m06'],'Respeite tanto a desigualdade estrita quanto a quantidade inteira.')
e(5,'Logaritmo e crescimento',r'Uma cultura tem $N(t)=200\cdot3^t$, com t em horas e t≥0.', 'Quando terá1 800 organismos?',r'Resolva $\log x+\log x^2+\log x^3=-6$, com log decimal.','2 h.','x=0,1.',[r'a)1800/200=9=3², então t=2.',r'b)Domínio x>0. Soma=(1+2+3)logx=6logx.',r'6logx=−6, logx=−1, x=10⁻¹=0,1.'],['m08','m09'],'Log x² é2logx no domínio x>0 imposto pelo primeiro termo.')
e(5,'Terreno e círculo','Um terreno triangular tem lados de20 e30 m que formam120°. Em outro desenho, um quadrado está inscrito em um círculo de raio5√2 cm. Use sen120°=√3/2.','Determine a área do terreno.','Determine o lado e a área do quadrado.','150√3 m².','10 cm;100 cm².',['a)A=20·30·sen120°/2=600·√3/4=150√3.','b)Diagonal2R=10√2;lado=diagonal/√2=10.','Área=10²=100.'],['m13','m12','m11'],'Use o ângulo compreendido entre os lados; círculo e terreno são situações independentes.')
e(5,'Conversões e velocidade média','Um percurso retilíneo no mesmo sentido tem dois trechos de60 km. O primeiro é feito a60 km/h; o segundo,a120 km/h.','Determine o tempo total e a velocidade média.','Um vetor de módulo54 km/h tem cosθ=0,6 e senθ=0,8,no primeiro quadrante. Ache suas componentes em m/s.','1,5 h;80 km/h.','9 e12 m/s.',['a)Tempos60/60=1h e60/120=0,5h. Média120/1,5=80.','b)54/3,6=15 m/s.','vx=15·0,6=9;vy=15·0,8=12.'],['p02','p01'],'A média de velocidades não é automaticamente a média aritmética.')
e(5,'Fosso e velocidade resultante','Uma esfera é lançada horizontalmente para atravessar um fosso de6 m. A plataforma de chegada está1,8 m abaixo da saída. Use g=10 m/s²,sem resistência do ar.','Determine a velocidade horizontal mínima.','Determine o módulo da velocidade quando a esfera atinge a borda na condição mínima.','10 m/s.','√136 m/s =2√34 m/s ≈11,66 m/s.',['a)1,8=5t²;t=0,6s. Velocidade mínima6/0,6=10.','b)vy=10·0,6=6.','v=√(10²+6²)=√136.'],['p04','p03'],'O tempo vem da queda vertical; a distância horizontal determina a velocidade mínima.')
e(5,'Sombras e luz','Uma haste de1,2 m projeta sombra de0,8 m. Ao mesmo tempo,um prédio projeta sombra de12 m.','Determine a altura do prédio.','Um raio faz60° com uma superfície refletora plana. Determine i e r com a normal. A imagem de um objeto a2 m do espelho está a que distância do objeto?','18 m.','i=r=30°;4 m.',['a)H/12=1,2/0,8=1,5;H=18.','b)i=90−60=30°,r=30°.','Imagem fica2m atrás;objeto2m à frente;total4m.'],['p07','p08'],'Na semelhança,relacione altura com altura e sombra com sombra.')
e(5,'Mistura com gelo','100 g de água a50°C são colocados com50 g de gelo a0°C em recipiente isolado de capacidade térmica desprezível. Use c_água=1 cal/(g·°C),L_f=80 cal/g.','Verifique se todo o gelo derrete.','Determine a temperatura de equilíbrio.','Sim:água pode ceder5000 cal;fusão exige4000 cal.','20/3°C≈6,67°C.',['a)Resfriar água até0°C libera100·1·50=5000cal;fundir gelo pede50·80=4000.','b)Sobram1000cal para aquecer150g de água.','1000=150·1·T;T=20/3°C.'],['p09'],'Primeiro teste a fusão completa; só então calcule a temperatura.')
e(5,'Comparação orbital','Dois planetas orbitam a mesma estrela. O planeta A tem aA=1 UA e TA=1 ano; o B tem aB=9 UA.','Determine TB e as coordenadas de ambos no gráfico horizontal a³ e vertical T².','O planeta B percorre arcos com áreas iguais perto e longe da estrela. Compare os tempos e as velocidades locais.','TB=27 anos;A=(1,1),B=(729,729).','Tempos iguais;velocidade maior perto da estrela.',['a)(TB/1)²=(9/1)³=729;TB=27.','No gráfico transformado os dois pontos ficam na retaT²=a³.','b)Segunda lei:áreas iguais,tempos iguais. No periélio,distância menor exige maior rapidez para manter a velocidade areolar.'],['p11'],'No gráfico da terceira lei, transforme os dois eixos, não só um.')
e(5,'Número de partículas',r'Considere ${}^{40}_{20}Ca^{2+}$ e ${}^{40}_{18}Ar$.','Compare prótons,nêutrons e elétrons e diga se são isoeletrônicos,isóbaros ou isótopos.','Escreva a configuração abreviada do Ca neutro e de Ca²⁺.','Ca²⁺:20p,20n,18e;Ar:18p,22n,18e. Isoeletrônicos e isóbaros,não isótopos.','Ca=[Ar]4s²;Ca²⁺=[Ar].',['a)N=A−Z;elétrons do cátion20−2=18. Igualdade de A faz isóbaros;Z diferente impede isótopos.','b)Neutro tem20e,dois apósAr.','Perde os dois4s ao formar o cátion.'],['q02','q03'],'Mudança de elétrons não muda a identidade do elemento.')
e(5,'Símbolos,grupos e ligações','Considere Na(Z=11),Cl(Z=17) e H₂O.','Identifique grupos de Na e Cl e formule o composto iônico entre eles.','Descreva Lewis da água e compare o tipo de ligação predominante com o do sal.','Na:grupo1;Cl:grupo17;NaCl.','H–O–H com dois pares livres;água covalente,NaCl iônico.',['a)Na tende a perder1e eCl a ganhar1e;Na⁺Cl⁻ é neutro.','b)Na água,O compartilha um par com cadaH e guarda dois pares.','No cristalNaCl,íons opostos se atraem numa rede.'],['q04','q05'],'A fórmula do sal expressa a proporção de íons,não uma molécula isolada de pares covalentes.')
e(5,'Mistura e proporção absorvida','Uma amostra escolar tem5 g de uma substância pura X e15 g de água. Num modelo de absorção hipotético,apenas40% de X é retido. M(X)=100 g/mol e cada molécula tem10 átomos. Use N_A=6×10²³.','Calcule a porcentagem em massa inicial de X e a quantidade em mol retida.','Determine o número de átomos provenientes de X retidos.','25%;0,02 mol.','1,2×10²³ átomos.',['a)Massa total20g;5/20=25%. Retidos0,4·5=2g;n=2/100=0,02.','b)Moléculas0,02·6×10²³=1,2×10²².','Cada uma tem10átomos,total1,2×10²³.'],['q01','q06','q07'],'A fração de X na mistura e a fração retida são porcentagens com bases diferentes.')
e(5,'Ácido,metal e gás','Zn+2HCl→ZnCl₂+H₂. Há6,5 g de Zn e0,15 mol de HCl. Use M(Zn)=65 g/mol e volume molar22,4 L/mol nas CNTP.','Classifique a reação e determine o limitante.','Determine o volume de H₂ e a massa de Zn que sobra.','Simples troca;HCl limita.','1,68 L;1,625 g.',['a)nZn=6,5/65=0,10;compare0,10/1 e0,15/2=0,075. HCl limita.','b)nH₂=0,075;V=0,075·22,4=1,68L.','Zn consumido0,075·65=4,875g;sobra6,5−4,875=1,625g.'],['q09','q08','q06'],'O ácido exige duas unidades molares por uma de zinco.')
e(5,'Carbonos e oxigênio',r'Considere $CH_3-CH(CH_3)-CH_2-CH_3$.','Nomeie o composto,dê a fórmula molecular e diga por que a ramificação entra na contagem.','Balanceie a combustão completa e calcule os mols de O₂ para0,25 mol do composto.','2-metilbutano;C₅H₁₂. A ramificação adiciona um carbono à cadeia principal de4.','C₅H₁₂+8O₂→5CO₂+6H₂O;2 mol de O₂.',['a)A cadeia mais longa tem4C e metil no2;total5C. Alcano aberto:H=2·5+2=12.','b)5C dão5CO₂,12H dão6H₂O;16O nos produtos exigem8O₂.','0,25·8=2mol deO₂.'],['q10','q08'],'Conte todos os carbonos, não apenas a cadeia escolhida para o nome.')
